//! Typed subprocess contracts for BigLinux Rust desktop apps.
//!
//! `BigSubprocessSpec` replaces raw `std::process::Command` for any
//! subprocess that crosses an untrusted-input boundary. It enforces:
//!
//! - argv list form (never `sh -c`);
//! - explicit timeout;
//! - explicit stdout/stderr capture mode;
//! - secret-redaction policy for log/error text;
//! - optional binary allow-list.
//!
//! Builder is generated by [`bon`] — required fields are checked at
//! compile time. The display-free `Resolved` value can be inspected in
//! tests without actually spawning a process. Use
//! [`crate::subprocess::BigSubprocessSpec::run`] for the synchronous spawn path. Async
//! wrappers can be added later behind a feature flag without breaking
//! the spec contract.
//!
//! # Examples
//!
//! ```
//! use big_os_kit::subprocess::{BigSubprocessSpec, BigSubprocessOutputMode};
//! use std::time::Duration;
//!
//! let spec = BigSubprocessSpec::builder()
//!     .program("ffprobe")
//!     .arg("-of")
//!     .arg("json")
//!     .arg("/tmp/file.mp4")
//!     .timeout(Duration::from_secs(10))
//!     .stdout(BigSubprocessOutputMode::Capture)
//!     .build();
//!
//! let resolved = spec.resolved();
//! assert_eq!(resolved.program, "ffprobe");
//! assert_eq!(resolved.argv, vec![
//!     "-of".to_string(),
//!     "json".to_string(),
//!     "/tmp/file.mp4".to_string(),
//! ]);
//! assert_eq!(resolved.timeout_ms, 10_000);
//! ```

use std::collections::HashSet;
use std::ffi::OsString;
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::Duration;

use bon::Builder;

/// Capture policy for a subprocess stream.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BigSubprocessOutputMode {
    /// Inherit the parent process stream (logs to terminal/console).
    Inherit,
    /// Capture into memory; available via [`BigSubprocessOutput::stdout`].
    Capture,
    /// Discard.
    Null,
}

/// Allow-list policy for the program (argv\[0\]).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct BigSubprocessAllowList {
    /// Set of program names that may be spawned. An empty set
    /// rejects every spawn, providing a deny-all baseline.
    pub allowed: HashSet<String>,
}

impl BigSubprocessAllowList {
    /// Build an allow-list from an iterator of items.
    #[must_use]
    pub fn new<S, I>(items: I) -> Self
    where
        S: Into<String>,
        I: IntoIterator<Item = S>,
    {
        Self {
            allowed: items.into_iter().map(Into::into).collect(),
        }
    }

    /// Returns `true` when the program is permitted.
    #[must_use]
    pub fn permits(&self, program: &str) -> bool {
        self.allowed.contains(program)
    }
}

/// Default subprocess timeout when caller does not set one explicitly.
pub const DEFAULT_TIMEOUT: Duration = Duration::from_secs(30);

/// Largest single stdout/stderr capture the runtime will retain.
/// Bounded to avoid OOM on hostile programs that emit unbounded output.
pub const DEFAULT_MAX_CAPTURE_BYTES: usize = 16 * 1024 * 1024;

/// Typed subprocess spec. argv form, timeout, redact, allow-list. Replaces
/// raw `Command::new` at trust boundaries.
///
/// All fields use owned types so the spec is easy to build in tests and
/// pass across thread boundaries. Construct with [`BigSubprocessSpec::builder`].
///
/// # Capabilities
///
/// `subprocess`, `subprocess+timeout`, `subprocess+allow-list`, `subprocess+redact`
///
/// # Archetypes
///
/// `terminal`, `pkg-manager`, `system-monitor`, `network-manager`, `container-manager`, `clipboard`, `screenshot`
///
/// # Examples
///
/// ```
/// use big_os_kit::subprocess::{BigSubprocessSpec, BigSubprocessOutputMode};
/// use std::time::Duration;
///
/// let spec = BigSubprocessSpec::builder()
///     .program("ffprobe")
///     .arg("-of")
///     .arg("json")
///     .arg("/tmp/file.mp4")
///     .timeout(Duration::from_secs(10))
///     .stdout(BigSubprocessOutputMode::Capture)
///     .build();
///
/// let r = spec.resolved();
/// assert_eq!(r.program, "ffprobe");
/// assert_eq!(r.timeout_ms, 10_000);
/// ```
#[derive(Debug, Clone, Builder)]
#[builder(start_fn = builder, finish_fn = build)]
pub struct BigSubprocessSpec {
    /// argv\[1..\] tokens. Push via the `.arg()` / `.args()` builder methods.
    #[builder(field)]
    pub(crate) argv: Vec<OsString>,

    /// Environment overrides applied on top of inherit policy.
    #[builder(field)]
    pub(crate) env_overrides: Vec<(OsString, OsString)>,

    /// Substrings redacted from captured stdout/stderr before return.
    /// Push via the `.redact()` builder method.
    #[builder(field)]
    pub(crate) redact_substrings: Vec<String>,

    /// Program (argv\[0\]) to spawn.
    #[builder(into)]
    pub(crate) program: String,

    /// Working directory for the child.
    #[builder(into)]
    pub(crate) cwd: Option<PathBuf>,

    /// When `false`, the parent environment is dropped before applying overrides.
    #[builder(default = true)]
    pub(crate) env_inherit: bool,

    /// Bytes piped to the child stdin. `None` = no stdin write.
    pub(crate) stdin: Option<Vec<u8>>,

    /// Stdout capture policy. Default: `Capture`.
    #[builder(default = BigSubprocessOutputMode::Capture)]
    pub(crate) stdout: BigSubprocessOutputMode,

    /// Stderr capture policy. Default: `Capture`.
    #[builder(default = BigSubprocessOutputMode::Capture)]
    pub(crate) stderr: BigSubprocessOutputMode,

    /// Maximum runtime before kill + [`BigSubprocessError::Timeout`].
    /// Default: 30 seconds.
    #[builder(default = DEFAULT_TIMEOUT)]
    pub(crate) timeout: Duration,

    /// Optional allow-list. When set, `try_resolved` rejects programs not
    /// in the list.
    pub(crate) allow: Option<BigSubprocessAllowList>,
}

// Extension methods on the bon-generated builder that implement
// accumulator setters for the `#[builder(field)]` vec fields. These
// keep the existing `.arg("x").arg("y")` chain ergonomic instead of
// forcing callers to construct vectors externally.
impl<S: big_subprocess_spec_builder::State> BigSubprocessSpecBuilder<S> {
    /// Append a single argv token.
    pub fn arg(mut self, value: impl Into<OsString>) -> Self {
        self.argv.push(value.into());
        self
    }

    /// Append multiple argv tokens.
    pub fn args<I, T>(mut self, values: I) -> Self
    where
        I: IntoIterator<Item = T>,
        T: Into<OsString>,
    {
        for v in values {
            self.argv.push(v.into());
        }
        self
    }

    /// Set a single environment override `key=value`.
    pub fn env(mut self, key: impl Into<OsString>, value: impl Into<OsString>) -> Self {
        self.env_overrides.push((key.into(), value.into()));
        self
    }

    /// Add a substring to redact from captured output.
    pub fn redact(mut self, needle: impl Into<String>) -> Self {
        self.redact_substrings.push(needle.into());
        self
    }

    /// Convenience: install an allow-list constructed from an iterator.
    pub fn allow_list<I, T>(
        self,
        items: I,
    ) -> BigSubprocessSpecBuilder<big_subprocess_spec_builder::SetAllow<S>>
    where
        I: IntoIterator<Item = T>,
        T: Into<String>,
        S::Allow: big_subprocess_spec_builder::IsUnset,
    {
        self.allow(BigSubprocessAllowList::new(items))
    }
}

impl BigSubprocessSpec {
    /// Largest single stdout/stderr capture the runtime will retain.
    pub const DEFAULT_MAX_CAPTURE_BYTES: usize = DEFAULT_MAX_CAPTURE_BYTES;

    /// Default timeout when caller does not set one explicitly.
    pub const DEFAULT_TIMEOUT: Duration = DEFAULT_TIMEOUT;

    /// Validate and resolve. Errors when the program is empty or fails
    /// the allow-list.
    ///
    /// # Errors
    ///
    /// Returns [`BigSubprocessError::EmptyProgram`] when the program string is empty,
    /// or [`BigSubprocessError::ProgramNotAllowed`] when an allow-list is set and the
    /// program is missing from it.
    pub fn try_resolved(&self) -> Result<BigSubprocessResolved, BigSubprocessError> {
        if self.program.is_empty() {
            return Err(BigSubprocessError::EmptyProgram);
        }
        // reject control bytes in program + argv (NUL/LF/CR/DEL)
        if let Some(byte) = argv_token_forbidden_byte(&self.program) {
            return Err(BigSubprocessError::ForbiddenArgvByte { index: 0, byte });
        }
        for (i, tok) in self.argv.iter().enumerate() {
            let s = tok.to_string_lossy();
            if let Some(byte) = argv_token_forbidden_byte(&s) {
                return Err(BigSubprocessError::ForbiddenArgvByte { index: i + 1, byte });
            }
        }
        if let Some(list) = &self.allow
            && !list.permits(&self.program)
        {
            return Err(BigSubprocessError::ProgramNotAllowed(self.program.clone()));
        }
        Ok(BigSubprocessResolved {
            program: self.program.clone(),
            argv: self
                .argv
                .iter()
                .map(|s| s.to_string_lossy().into_owned())
                .collect(),
            cwd: self.cwd.clone(),
            env_overrides: self
                .env_overrides
                .iter()
                .map(|(k, v)| {
                    (
                        k.to_string_lossy().into_owned(),
                        v.to_string_lossy().into_owned(),
                    )
                })
                .collect(),
            env_inherit: self.env_inherit,
            stdin_len: self.stdin.as_ref().map(Vec::len).unwrap_or(0),
            stdout: self.stdout,
            stderr: self.stderr,
            timeout_ms: u64::try_from(self.timeout.as_millis()).unwrap_or(u64::MAX),
            redact_substrings: self.redact_substrings.clone(),
        })
    }

    /// Resolve, panicking on invalid spec. Use in tests and contexts where
    /// the spec is statically known to be valid.
    ///
    /// # Panics
    ///
    /// Panics if [`Self::try_resolved`] returns an error.
    #[must_use]
    pub fn resolved(&self) -> BigSubprocessResolved {
        self.try_resolved()
            .expect("BigSubprocessSpec must validate")
    }

    /// Spawn the subprocess synchronously and wait for completion.
    ///
    /// Captures stdout/stderr if their modes are [`BigSubprocessOutputMode::Capture`].
    /// Linux: returns after the leader exits AND captured pipes reach EOF.
    /// The deadline supervises stdin, both captured outputs and descendant-held
    /// pipes. Creation/system-call latency is not a hard real-time guarantee.
    /// Timeout/cancel/overflow kills the owned process group; collection is
    /// deferred without a blocking join. `spawn()` retains its caller-owned API.
    /// Captures exceeding the limit fail explicitly rather than truncating.
    /// Non-Linux bounded execution returns Unsupported before creating a child.
    ///
    /// # Errors
    ///
    /// Returns [`BigSubprocessError::Spawn`] if the process cannot be started,
    /// [`BigSubprocessError::Io`] on stream I/O errors,
    /// or [`BigSubprocessError::Timeout`] if the configured timeout elapses.
    pub fn run(&self) -> Result<BigSubprocessOutput, BigSubprocessError> {
        // Never-set cancel flag: identical timeout/exit behavior to the
        // cancellable path, so both share one drain/kill loop.
        self.run_cancellable(&AtomicBool::new(false))
    }

    /// Spawn the subprocess synchronously and wait, honouring an external
    /// cancellation flag in addition to the spec timeout.
    ///
    /// Behaves exactly like [`Self::run`] — same concurrent stdout/stderr
    /// draining, same timeout-kill path — but the wait loop also breaks when
    /// `cancel` becomes `true`. On cancellation the child is killed (the same
    /// kill path as timeout) and [`BigSubprocessError::Cancelled`] is returned.
    ///
    /// The flag is polled on the same ~20 ms cadence as the deadline, so a
    /// flipped `cancel` is checked between bounded I/O turns; scheduling and
    /// process creation latency can exceed this polling interval. Share the flag with the UI thread (e.g. `Arc<AtomicBool>`
    /// flipped on component teardown) to bind a subprocess to a widget
    /// lifetime; see
    /// [`big_relm4_components::task`](../../big_relm4_components/task/index.html)
    /// for the Relm4-bound helper.
    ///
    /// # Errors
    ///
    /// As [`Self::run`], plus [`BigSubprocessError::Cancelled`] when `cancel`
    /// is set before the child exits.
    pub fn run_cancellable(
        &self,
        cancel: &AtomicBool,
    ) -> Result<BigSubprocessOutput, BigSubprocessError> {
        let resolved = self.try_resolved()?;
        run_resolved(self, &resolved, cancel)
    }

    /// Run with bounded, incremental stderr observation on the supervising
    /// thread. The observer MUST NOT block (use try_send for progress); its I/O
    /// error cancels the process group. Bytes are untrusted and unredacted here:
    /// parse only protocol fields, never forward them wholesale to logs/UI.
    /// Capture limits still apply and truncation is never reported as success.
    pub fn run_cancellable_with_stderr(
        &self, cancel: &AtomicBool,
        observer: &mut dyn FnMut(&[u8]) -> std::io::Result<()>,
    ) -> Result<BigSubprocessOutput, BigSubprocessError> {
        self.try_resolved()?;
        #[cfg(target_os = "linux")]
        { linux_exec::run_observed(self, cancel, observer) }
        #[cfg(not(target_os = "linux"))]
        { let _ = (cancel, observer); Err(BigSubprocessError::Io(std::io::Error::new(std::io::ErrorKind::Unsupported, "bounded observation requires Linux"))) }
    }

    /// Spawn the subprocess without waiting and return a
    /// [`BigSubprocessChild`] handle for streaming and lifecycle control.
    ///
    /// Use this for long-running children (media players, transcoders,
    /// daemons) that out-live a single `run()` call or whose output must be
    /// consumed incrementally. argv / allow-list / forbidden-byte
    /// validation applies exactly as in [`Self::run`], but the spec
    /// `timeout` is **not** enforced — the caller owns the child's lifetime
    /// via the returned handle.
    ///
    /// stdin/stdout/stderr follow the spec's modes; piped streams are
    /// exposed via [`BigSubprocessChild::take_stdout`] / `take_stderr` /
    /// `take_stdin`. Any `stdin` payload set on the spec is **not**
    /// auto-written here.
    ///
    /// # Errors
    ///
    /// Returns [`BigSubprocessError::EmptyProgram`],
    /// [`BigSubprocessError::ProgramNotAllowed`], or
    /// [`BigSubprocessError::ForbiddenArgvByte`] on validation failure, or
    /// [`BigSubprocessError::Spawn`] if the process cannot be started.
    pub fn spawn(&self) -> Result<BigSubprocessChild, BigSubprocessError> {
        self.try_resolved()?;
        let child = build_command(self)
            .spawn()
            .map_err(BigSubprocessError::Spawn)?;
        notify_spawn_observer(child.id(), &self.program);
        Ok(BigSubprocessChild { child })
    }

    /// Spawn fully detached (fire-and-forget) for launching helper programs
    /// (`xdg-open`, an external editor) where the parent neither reads
    /// output nor waits.
    ///
    /// stdin/stdout/stderr are redirected to null regardless of the spec's
    /// capture modes; a bounded shared worker reaps the child. Validation
    /// applies as in [`Self::spawn`].
    ///
    /// # Errors
    ///
    /// As [`Self::spawn`].
    pub fn spawn_detached(&self) -> Result<(), BigSubprocessError> {
        use std::process::Stdio;
        self.try_resolved()?;
        let permit = reaper::Permit::reserve().map_err(BigSubprocessError::Io)?;
        let mut cmd = build_command(self);
        cmd.stdin(Stdio::null());
        cmd.stdout(Stdio::null());
        cmd.stderr(Stdio::null());
        let detached_child = cmd.spawn().map_err(BigSubprocessError::Spawn)?;
        let pid = detached_child.id();
        permit.defer(detached_child);
        notify_spawn_observer(pid, &self.program);
        Ok(())
    }
}

/// Process-wide spawn observer: every successful spawn from this crate
/// (run / spawn / spawn_detached) reports `(pid, program)` here. One
/// consumer per process, set once (first call wins) — designed for
/// multi-app hosts (big-host) that route engine children into per-module
/// cgroup scopes. Spawns can happen on worker threads, so the observer
/// must be `Send + Sync` and cheap.
/// Boxed `(pid, program)` callback type for [`set_spawn_observer`].
pub type BigSpawnObserver = Box<dyn Fn(u32, &str) + Send + Sync>;

static SPAWN_OBSERVER: std::sync::OnceLock<BigSpawnObserver> = std::sync::OnceLock::new();

/// Install the process-wide spawn observer. Later calls are ignored.
pub fn set_spawn_observer(observer: impl Fn(u32, &str) + Send + Sync + 'static) {
    let _ = SPAWN_OBSERVER.set(Box::new(observer));
}

pub(crate) fn notify_spawn_observer(pid: u32, program: &str) {
    if let Some(observer) = SPAWN_OBSERVER.get() {
        observer(pid, program);
    }
}

/// Handle to a running child spawned via [`BigSubprocessSpec::spawn`].
///
/// The caller owns the lifecycle: read the exposed pipes, then
/// [`Self::wait`] (or poll with [`Self::try_wait`]) or [`Self::kill`].
/// Dropping the handle without waiting leaves the child running and, on
/// Unix, unreaped until this process exits — call `wait`/`kill` explicitly.
#[derive(Debug)]

pub struct BigSubprocessChild {
    child: std::process::Child,
}

impl BigSubprocessChild {
    /// OS process id of the child.
    #[must_use]
    pub fn id(&self) -> u32 {
        self.child.id()
    }

    /// Take the captured stdout pipe (present only when the spec's stdout
    /// mode is [`BigSubprocessOutputMode::Capture`]). Returns `None` after
    /// the first take.
    #[must_use]
    pub fn take_stdout(&mut self) -> Option<std::process::ChildStdout> {
        self.child.stdout.take()
    }

    /// Take the captured stderr pipe; see [`Self::take_stdout`].
    #[must_use]
    pub fn take_stderr(&mut self) -> Option<std::process::ChildStderr> {
        self.child.stderr.take()
    }

    /// Take the stdin pipe (present only when the spec set a `stdin`
    /// payload). Returns `None` after the first take.
    #[must_use]
    pub fn take_stdin(&mut self) -> Option<std::process::ChildStdin> {
        self.child.stdin.take()
    }

    /// Poll without blocking. Returns `Ok(None)` while the child runs.
    ///
    /// # Errors
    ///
    /// Returns [`BigSubprocessError::Io`] on a wait syscall failure.
    pub fn try_wait(&mut self) -> Result<Option<BigSubprocessStatus>, BigSubprocessError> {
        self.child
            .try_wait()
            .map(|opt| opt.map(|status| BigSubprocessStatus::Exited(status.code())))
            .map_err(BigSubprocessError::Io)
    }

    /// Block until the child exits.
    ///
    /// # Errors
    ///
    /// Returns [`BigSubprocessError::Io`] on a wait syscall failure.
    pub fn wait(&mut self) -> Result<BigSubprocessStatus, BigSubprocessError> {
        self.child
            .wait()
            .map(|status| BigSubprocessStatus::Exited(status.code()))
            .map_err(BigSubprocessError::Io)
    }

    /// Kill the child (best-effort; idempotent on an already-exited child).
    ///
    /// # Errors
    ///
    /// Returns [`BigSubprocessError::Io`] if the kill syscall fails for a
    /// still-running child.
    pub fn kill(&mut self) -> Result<(), BigSubprocessError> {
        self.child.kill().map_err(BigSubprocessError::Io)
    }
}

/// Display-free, serde-friendly view of a resolved subprocess spec.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BigSubprocessResolved {
    /// Validated program (argv\[0\]).
    pub program: String,
    /// argv\[1..\] tokens as strings.
    pub argv: Vec<String>,
    /// Working directory, if explicitly set.
    pub cwd: Option<PathBuf>,
    /// Environment overrides resolved to strings.
    pub env_overrides: Vec<(String, String)>,
    /// Inherits the parent environment when `true`; set `false` for
    /// reproducible builds and to keep host secrets out of child procs.
    pub env_inherit: bool,
    /// Length of the stdin payload (0 = none).
    pub stdin_len: usize,
    /// Stdout capture policy.
    pub stdout: BigSubprocessOutputMode,
    /// Stderr capture policy.
    pub stderr: BigSubprocessOutputMode,
    /// Timeout in milliseconds.
    pub timeout_ms: u64,
    /// Substrings to redact from captured output.
    pub redact_substrings: Vec<String>,
}

/// Result of a completed subprocess run.
#[derive(Debug, Clone)]
pub struct BigSubprocessOutput {
    /// Exit status.
    pub status: BigSubprocessStatus,
    /// Captured stdout bytes (empty when stdout mode is not `Capture`).
    pub stdout: Vec<u8>,
    /// Captured stderr bytes (empty when stderr mode is not `Capture`).
    pub stderr: Vec<u8>,
}

impl BigSubprocessOutput {
    /// stdout as lossy UTF-8.
    #[must_use]
    pub fn stdout_lossy(&self) -> String {
        String::from_utf8_lossy(&self.stdout).into_owned()
    }

    /// stderr as lossy UTF-8.
    #[must_use]
    pub fn stderr_lossy(&self) -> String {
        String::from_utf8_lossy(&self.stderr).into_owned()
    }
}

/// Exit outcome.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BigSubprocessStatus {
    /// Process exited with the given status code (or `None` on signal exit).
    Exited(Option<i32>),
}

impl BigSubprocessStatus {
    /// `true` when the child returned exit code 0.
    #[must_use]
    pub fn success(self) -> bool {
        matches!(self, Self::Exited(Some(0)))
    }

    /// Exit code, or `None` when the child was terminated by a signal.
    /// Mirrors `std::process::ExitStatus::code`.
    #[must_use]
    pub fn code(self) -> Option<i32> {
        match self {
            Self::Exited(code) => code,
        }
    }
}

/// Failure modes when validating or running a subprocess spec.
#[derive(Debug, thiserror::Error)]
pub enum BigSubprocessError {
    /// Program field is empty.
    #[error("subprocess program is empty")]
    EmptyProgram,
    /// Program rejected by allow-list.
    #[error("program not in allow-list: {0}")]
    ProgramNotAllowed(String),
    /// `std::process::Command::spawn` failed.
    #[error("failed to spawn: {0}")]
    Spawn(#[source] std::io::Error),
    /// I/O error while reading stdout/stderr or writing stdin.
    #[error("subprocess i/o error: {0}")]
    Io(#[source] std::io::Error),
    /// Capture exceeded the documented memory limit; no partial success is returned.
    #[error("subprocess {stream} exceeded capture limit of {limit} bytes")]
    OutputLimit {
        /// Output stream that exceeded its cap.
        stream: &'static str,
        /// Maximum bytes retained for one output stream.
        limit: usize,
    },
    /// Configured timeout elapsed before all requested I/O completed.
    #[error("subprocess timed out")]
    Timeout,
    /// External cancellation flag was set before the child exited. The child
    /// was killed on the same path as [`Self::Timeout`].
    #[error("subprocess cancelled")]
    Cancelled,
    /// argv token contains a forbidden control character.
    ///
    /// Rejects `\0` (kernel argv terminator), `\n` / `\r` (log-injection
    /// vectors when stderr is parsed), and `\x7f` DEL (often present in
    /// crafted argv that smuggles past loose string allow-lists). Index
    /// is `0` for the program field, `1..` for the argv tail.
    #[error("argv token at index {index} contains forbidden control byte 0x{byte:02x}")]
    ForbiddenArgvByte {
        /// `0` for program, `1..` for argv\[i-1\].
        index: usize,
        /// Offending byte.
        byte: u8,
    },
}

// Reject NUL, LF, CR, DEL in any argv token. Keeps the spec compatible
// with the kernel argv contract and with naive log parsers downstream.
fn argv_token_forbidden_byte(s: &str) -> Option<u8> {
    s.bytes().find(|b| matches!(b, 0x00 | 0x0a | 0x0d | 0x7f))
}

fn stdio_for(mode: BigSubprocessOutputMode) -> std::process::Stdio {
    use std::process::Stdio;
    match mode {
        BigSubprocessOutputMode::Inherit => Stdio::inherit(),
        BigSubprocessOutputMode::Capture => Stdio::piped(),
        BigSubprocessOutputMode::Null => Stdio::null(),
    }
}

/// Build the `std::process::Command` for a spec: argv form, cwd, env
/// policy, and the configured stdin/stdout/stderr modes. Shared by the
/// blocking [`BigSubprocessSpec::run`] and the streaming
/// [`BigSubprocessSpec::spawn`] paths so both honour the same contract.
fn build_command(spec: &BigSubprocessSpec) -> std::process::Command {
    use std::process::{Command, Stdio};

    let mut cmd = Command::new(&spec.program);
    cmd.args(&spec.argv);
    if let Some(dir) = &spec.cwd {
        cmd.current_dir(dir);
    }
    if !spec.env_inherit {
        cmd.env_clear();
    }
    for (k, v) in &spec.env_overrides {
        cmd.env(k, v);
    }
    cmd.stdin(if spec.stdin.is_some() {
        Stdio::piped()
    } else {
        Stdio::null()
    });
    cmd.stdout(stdio_for(spec.stdout));
    cmd.stderr(stdio_for(spec.stderr));
    cmd
}

#[cfg(target_os = "linux")]
mod linux_exec;
pub(crate) mod reaper;

fn run_resolved(
    spec: &BigSubprocessSpec,
    _resolved: &BigSubprocessResolved,
    cancel: &AtomicBool,
) -> Result<BigSubprocessOutput, BigSubprocessError> {
    #[cfg(target_os = "linux")]
    { linux_exec::run(spec, cancel) }
    #[cfg(not(target_os = "linux"))]
    { let _ = (spec, cancel); Err(BigSubprocessError::Io(std::io::Error::new(
        std::io::ErrorKind::Unsupported, "bounded run requires the Linux pipe supervisor"))) }
}

#[cfg(test)]
fn drain_capped<R: std::io::Read>(reader: &mut R, buf: &mut Vec<u8>) -> Result<(), BigSubprocessError> {
    let mut chunk = [0_u8; 8192];
    loop {
        match reader.read(&mut chunk) {
            Ok(0) => return Ok(()),
            Ok(n) => {
                if n > DEFAULT_MAX_CAPTURE_BYTES.saturating_sub(buf.len()) {
                    return Err(BigSubprocessError::OutputLimit { stream: "capture", limit: DEFAULT_MAX_CAPTURE_BYTES });
                }
                buf.extend_from_slice(&chunk[..n]);
            }
            Err(error) if error.kind() == std::io::ErrorKind::Interrupted => {},
            Err(error) => return Err(BigSubprocessError::Io(error)),
        }
    }
}

fn redact_in_place(needles: &[String], buf: &mut Vec<u8>) {
    if needles.iter().all(String::is_empty) { return; }
    let mut out = Vec::with_capacity(buf.len().min(DEFAULT_MAX_CAPTURE_BYTES));
    let mut pos = 0;
    // Match only original bytes, longest match first. Redaction never skips a
    // buffer merely because another byte in it is invalid UTF-8.
    while pos < buf.len() && out.len() < DEFAULT_MAX_CAPTURE_BYTES {
        let length = needles.iter().filter(|n| !n.is_empty() && buf[pos..].starts_with(n.as_bytes()))
            .map(String::len).max();
        if let Some(length) = length {
            let marker = b"[REDACTED]";
            if marker.len() > DEFAULT_MAX_CAPTURE_BYTES - out.len() { break; }
            out.extend_from_slice(marker); pos += length;
        } else { out.push(buf[pos]); pos += 1; }
    }
    *buf = out;
}

#[cfg(test)]
mod tests;

#[cfg(test)]
mod review_allow_list_tests {
    use super::*;

    #[test]
    fn empty_allow_list_denies_every_program() {
        let policy = BigSubprocessAllowList::default();
        assert!(!policy.permits("sh"));
        assert!(!policy.permits("/usr/bin/true"));
    }

    #[test]
    fn permission_matches_the_exact_executable() {
        let policy = BigSubprocessAllowList::new(["pactl"]);
        assert!(policy.permits("pactl"));
        assert!(!policy.permits("/tmp/pactl"));
        assert!(!policy.permits("sh"));
    }
}
